const inputItems = $input.all();
const normalizedItems = $('Classify Image Input Mode').all();
const outputItems = [];

const passthroughKeys = [
  'taskIndex', 'sceneIndex', 'sceneKey', 'sceneTitle', 'title', 'titleDescription',
  'taskDir', 'promptFileName', 'promptFilePath', 'productDetailFileName',
  'productDetailFilePath', 'rootOutputDir', 'productName', 'productDescription',
  'productAppearance', 'targetPlatform', 'targetMarket', 'ratio', 'timestamp',
  'workflowId', 'n8nExecutionId', 'sourceSubmissionId', 'viewImageMeta', 'sourceViewImages',
  'batchIndex', 'generationConcurrency', 'originalIndex', 'imageInputMode', 'constants'
];

function text(value) {
  return value === undefined || value === null ? '' : String(value);
}

function isHttpUrl(value) {
  return /^https?:\/\//i.test(text(value).trim());
}

for (let itemIndex = 0; itemIndex < inputItems.length; itemIndex++) {
  const item = inputItems[itemIndex];
  const binary = item.binary || {};
  const source = normalizedItems[itemIndex]?.json || {};
  const prompt = text(source.prompt).trim();
  const negativePrompt = text(source.negativePrompt).trim();

  if (!prompt) {
    throw new Error(
      'Prepare Jimeng Image Input: missing prompt for itemIndex=' + itemIndex +
      ', taskIndex=' + text(source.taskIndex) +
      ', sceneKey=' + text(source.sceneKey) +
      ', originalIndex=' + text(source.originalIndex)
    );
  }

  const images = [];
  const images_base64 = [];
  const image_meta = [];

  if (source.imageInputMode === 'url') {
    for (let i = 1; i <= 5; i++) {
      const key = 'image-' + i;
      const url = text(source[key]).trim();
      if (!url) continue;
      if (!isHttpUrl(url)) throw new Error('Invalid HTTP image URL in ' + key + ' for itemIndex=' + itemIndex);
      images.push(url);
      image_meta.push({ key: 'image_' + i, source: 'siliconflow-url', url });
    }
  } else {
    for (let i = 1; i <= 5; i++) {
      const key = 'image_' + i;
      const bin = binary[key];
      if (!bin) continue;

      const mimeType = bin.mimeType || 'image/png';
      let buffer;
      try {
        buffer = await this.helpers.getBinaryDataBuffer(itemIndex, key);
      } catch (error) {
        if (bin.data && typeof bin.data === 'string') {
          const rawBase64 = bin.data.replace(/^data:[^;]+;base64,/, '');
          buffer = Buffer.from(rawBase64, 'base64');
        } else {
          throw new Error('Cannot read binary field ' + key + ': ' + error.message);
        }
      }

      const base64 = buffer.toString('base64');
      images.push('data:' + mimeType + ';base64,' + base64);
      images_base64.push(base64);
      image_meta.push({
        key,
        source: 'local-base64',
        mimeType,
        fileName: bin.fileName || (key + '.' + (bin.fileExtension || 'png')),
        fileExtension: bin.fileExtension || '',
        fileSize: buffer.length,
      });
    }
  }

  if (!images.length) {
    throw new Error(
      'No images were prepared for itemIndex=' + itemIndex +
      ', taskIndex=' + text(source.taskIndex) +
      ', sceneKey=' + text(source.sceneKey) +
      ', imageInputMode=' + text(source.imageInputMode)
    );
  }

  const passthrough = {};
  for (const key of passthroughKeys) {
    if (source[key] !== undefined) passthrough[key] = source[key];
  }

  outputItems.push({
    json: {
      ...passthrough,
      prompt,
      negativePrompt,
      model: source.constants.model.jimengModel,
      resolution: source.resolution || '2k',
      ratio: source.ratio || '1:1',
      images,
      images_base64,
      image_count: images.length,
      image_meta,
    },
    pairedItem: { item: itemIndex },
  });
}

return outputItems;

const root = $input.first()?.json || {};
const constants = root.constants;
function requireConstant(value, field) {
  const text = typeof value === 'string' ? value.trim() : '';
  if (!text) throw new Error('CONFIG_INVALID: Global Constants 缺少 ' + field);
  return text;
}
const jimengModel = requireConstant(constants?.model?.jimengModel, 'constants.model.jimengModel');
const jimengUrl = requireConstant(constants?.BaseUrl?.JimengUrl, 'constants.BaseUrl.JimengUrl');
requireConstant(constants?.Authorization?.jimengAuthorValue, 'constants.Authorization.jimengAuthorValue');
const jimengUrlMatch = /^(https?):\/\/(\[[0-9a-f:.]+\]|[a-z0-9.-]+)(?::([0-9]{1,5}))?\/?$/i.exec(jimengUrl);
const jimengPort = jimengUrlMatch?.[3] ? Number(jimengUrlMatch[3]) : null;
if (!jimengUrlMatch || (jimengPort !== null && (jimengPort < 1 || jimengPort > 65535))) {
  throw new Error('CONFIG_INVALID: constants.BaseUrl.JimengUrl 必须是合法的 HTTP(S) 服务根地址');
}
const sourceItems = Array.isArray(root.batchItems) && root.batchItems.length ? root.batchItems : [root];
const hardLimit = 7;
