  if (/^(png|jpe?g|webp)$/.test(explicit)) return explicit === 'jpeg' ? 'jpg' : explicit;
  const mime = text(meta?.mimeType).toLowerCase();
  if (mime.includes('jpeg')) return 'jpg';
  if (mime.includes('webp')) return 'webp';
  if (mime.includes('png')) return 'png';
  if (/^https?:\/\//i.test(image)) {
    try {
      const match = new URL(image).pathname.match(/\.([a-z0-9]+)$/i);
      if (match && /^(png|jpe?g|webp)$/i.test(match[1])) return match[1].toLowerCase() === 'jpeg' ? 'jpg' : match[1].toLowerCase();
    } catch (error) {}
  }
  return 'png';
