const suppliedSubmissionId = text(first.sourceSubmissionId);
const sourceSubmissionId = suppliedSubmissionId || (n8nExecutionId
  ? (items.length === 7 ? 'E003:' : 'S003:') + n8nExecutionId
  : 'S003:' + String($execution.id || 'unknown'));

const images = Array.isArray(first.images) ? first.images.map(text).filter(Boolean) : [];
if (images.length < 1 || images.length > 10) {
  throw new Error('S003 async submit requires 1-10 prepared images.');
}
if (images.some((value) => !/^https?:\/\//i.test(value) && !/^data:image\/(?:png|jpe?g|webp);base64,/i.test(value))) {
