    E002: Object.freeze({ initialMs: 0, retryMs: 0, maxPollCount: 120, intervalMs: 10000 }),
    S003: Object.freeze({ initialMs: 300000, retryMs: 300000, maxPollCount: 0, intervalMs: 10000 }),
