  return Object.freeze({ version, targetImageCount, minimumSuccessImageCount: 1, maxRegenerations: 1, profiles, urlKey, urls, evaluate, timing });
})();

const output=originalBuild();
for(const item of output) {
 if("S003"==='S003') item.json.completionPolicy={targetImageCount:imagePolicy.targetImageCount,minimumSuccessImageCount:imagePolicy.minimumSuccessImageCount,attemptTimeoutMs:imagePolicy.profiles.S003.initialMs};
 for(const task of item.json.tasks || []) {
